from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from fractions import Fraction

_CENT = Decimal("0.01")


def _parse(value):
    if not isinstance(value, str):
        raise ValueError("input must be a string")
    try:
        number = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid decimal: {value!r}") from None
    if not number.is_finite():
        raise ValueError("input must be finite")
    return number


def _frac_from_decimal(d: Decimal) -> Fraction:
    # d = int(digits) * 10**exp with sign
    tup = d.as_tuple()
    sign = -1 if tup.sign else 1
    if tup.digits == (0,):
        return Fraction(0, 1)
    # build integer from digits
    int_val = 0
    for dig in tup.digits:
        int_val = int_val * 10 + dig
    int_val *= sign
    exp = tup.exponent
    if exp >= 0:
        # int_val * 10**exp / 1
        if int_val == 0:
            return Fraction(0, 1)
        return Fraction(int_val * (10 ** exp), 1)
    else:
        # int_val / 10**(-exp)
        return Fraction(int_val, 10 ** (-exp))


def _round_half_up_frac(frac: Fraction) -> int:
    # round frac to nearest integer, halves away from zero
    if frac == 0:
        return 0
    if frac > 0:
        # floor(frac + 1/2) = (2*num + den) // (2*den)
        num = frac.numerator
        den = frac.denominator
        return (2 * num + den) // (2 * den)
    else:
        # for negative: - round_half_up(-frac)
        num = -frac.numerator  # positive
        den = frac.denominator
        return - ((2 * num + den) // (2 * den))


def _quantize_frac_to_2dp(frac: Fraction) -> Decimal:
    # quantize frac to exactly 2 dp with HALF_UP
    # compute cents = round_half_up(frac * 100)
    cents_frac = frac * 100  # Fraction
    cents = _round_half_up_frac(cents_frac)
    # construct Decimal with exponent -2 exactly: Decimal(cents).scaleb(-2)
    # scaleb preserves exponent exactly
    return Decimal(cents).scaleb(-2)


def percent_change(old: str, new: str) -> Decimal | None:
    old_d, new_d = _parse(old), _parse(new)
    if old_d == 0:
        return Decimal("0.00") if new_d == 0 else None
    old_frac = _frac_from_decimal(old_d)
    new_frac = _frac_from_decimal(new_d)
    # (new - old) / abs(old) * 100
    # abs(old) = abs(old_frac)
    abs_old = abs(old_frac)
    change_frac = (new_frac - old_frac) / abs_old * 100
    return _quantize_frac_to_2dp(change_frac)


def apply_percent_change(old: str, percent: str) -> Decimal:
    old_d, pct = _parse(old), _parse(percent)
    old_frac = _frac_from_decimal(old_d)
    pct_frac = _frac_from_decimal(pct)
    result_frac = old_frac * (1 + pct_frac / 100)
    return _quantize_frac_to_2dp(result_frac)
